        mov     ax, moview__row             ; link-time constant
        mov     [viewRow__at], ax
        mov     ax, [viewRenderRow__n]
        mov     [viewRow__n], ax
        call    viewRow
        ret

; ============================================== sub viewRender ====

viewRender:
; ---- for ( u16 y = 0; y < height; y++ ) {
        mov     word [viewRender__y], 0
.L247:
        mov     ax, [viewRender__y]
        mov     bx, [moview__height]
        cmp     ax, bx
        jae     .L249                       ; unsigned <
; ---- viewRenderRow( y )
        mov     ax, [viewRender__y]
        mov     [viewRenderRow__y], ax
        call    viewRenderRow
.L248:
        inc     word [viewRender__y]
        jmp     .L247
.L249:
        ret

; ============================================== sub viewRow ====

viewRow:
; ---- base = y * edCols
        mov     ax, [viewRow__y]
        mov     bx, 80
        mul     bx                          ; low 16 bits are sign-agnostic
        mov     [viewRow__base], ax
; ---- hi = u16( attrText ) << 8
        mov     al, [attrText]
        xor     ah, ah                      ; u8 -> u16
        mov     cl, 8                       ; 8086 has no shift-by-immediate
        shl     ax, cl
        mov     [viewRow__hi], ax
; ---- for ( u16 x = 0; x < n; x++ ) {
        mov     word [viewRow__x], 0
.L251:
        mov     ax, [viewRow__x]
        mov     bx, [viewRow__n]
        cmp     ax, bx
        jae     .L253                       ; unsigned <
; ---- vram[ base + x ] = u16( peek8( at + x ) ) | hi
        mov     ax, [viewRow__at]
        mov     bx, [viewRow__x]
        add     ax, bx
        mov     bx, ax
        mov     al, [bx]                    ; peek8 - unchecked, by design
        xor     ah, ah                      ; u8 -> u16
        mov     bx, [viewRow__hi]
        or      ax, bx
        push    ax                          ; save value while computing the index
        mov     ax, [viewRow__base]
        mov     bx, [viewRow__x]
        add     ax, bx
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     dx, [vramSeg]               ; segment of vram
        mov     es, dx
        pop     ax
        mov     [es:bx], ax
.L252:
        inc     word [viewRow__x]
        jmp     .L251
.L253:
; ---- for ( u16 x = n; x < edCols; x++ ) {
        mov     ax, [viewRow__n]
        mov     [viewRow__x], ax
.L255:
        mov     ax, [viewRow__x]
        cmp     ax, 80
        jae     .L257                       ; unsigned <
; ---- vram[ base + x ] = 32 | hi
        mov     ax, 32
        mov     bx, [viewRow__hi]
        or      ax, bx
        push    ax                          ; save value while computing the index
        mov     ax, [viewRow__base]
        mov     bx, [viewRow__x]
        add     ax, bx
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     dx, [vramSeg]               ; segment of vram
        mov     es, dx
        pop     ax
        mov     [es:bx], ax
.L256:
        inc     word [viewRow__x]
        jmp     .L255
.L257:
        ret

; ============================================== u16 perSecond ====

perSecond:
; ---- if ( spent == 0 ) return 0
        mov     ax, [perSecond__spent]
        test    ax, ax
        jne     .L259                       ; unsigned ==
        mov     word [perSecond__ret], 0
        ret
.L259:
; ---- return done / spent * ticksPerSecond + ( done % spent ) * ticksPerSecond / spent
        mov     ax, [perSecond__done]
        mov     bx, [perSecond__spent]
        xor     dx, dx                      ; clear high half for div
        div     bx
        mov     bx, 18
        mul     bx                          ; low 16 bits are sign-agnostic
        push    ax                          ; save lhs: rhs is not a leaf
        mov     ax, [perSecond__done]
        mov     bx, [perSecond__spent]
        xor     dx, dx                      ; clear high half for div
        div     bx
        mov     ax, dx                      ; remainder
        mov     bx, 18
        mul     bx                          ; low 16 bits are sign-agnostic
        mov     bx, [perSecond__spent]
        xor     dx, dx                      ; clear high half for div
        div     bx
        mov     bx, ax
        pop     ax
        add     ax, bx
        mov     [perSecond__ret], ax
        ret

; ============================================== sub report ====

report:
; ---- putStr( label )
        mov     ax, [report__label]
        mov     [putStr__at], ax
        call    putStr
; ---- putNumber( done )
        mov     ax, [report__done]
        mov     [putNumber__n], ax
        call    putNumber
; ---- putStr( addr( sDraws ) )
        mov     ax, sDraws                  ; link-time constant
        mov     [putStr__at], ax
        call    putStr
; ---- putNumber( spent )
        mov     ax, [report__spent]
        mov     [putNumber__n], ax
        call    putNumber
; ---- putStr( addr( sTicks ) )
        mov     ax, sTicks                  ; link-time constant
        mov     [putStr__at], ax
        call    putStr
; ---- putNumber( perSecond( done, spent ) )
        mov     ax, [report__done]
        mov     [perSecond__done], ax
        mov     ax, [report__spent]
        mov     [perSecond__spent], ax
        call    perSecond
        mov     ax, [perSecond__ret]
        mov     [putNumber__n], ax
        call    putNumber
; ---- putStr( addr( sRate ) )
        mov     ax, sRate                   ; link-time constant
        mov     [putStr__at], ax
        call    putStr
; ---- newline()
        call    newline
        ret

; ==================================================== int helpers ====
; One per distinct interrupt: the literal is baked in, so the register
; sync is emitted once rather than at every call site.

int10:
        push    es
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x10
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pop     es
        ret

int21:
        push    es
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x21
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pop     es
        ret

